for(const side of [-1,1])for(let z=-15;z<=15;z+=10){box(scene,[side*20.52,2.8,z],[.12,1.2,3.2],mats.dark,false);for(let j=0;j<5;j++)box(scene,[side*20.43,2.8,z-1+j*.48],[.08,.055,2.5],mats.trim,false);box(scene,[side*19.7,.65,z],[.8,1.3,1.1],mats.dark);box(scene,[side*19.27,1,z],[.04,.45,.62],mats.cyan,false)}
// First-person field weapon, assembled from original procedural geometry.
const gun=new THREE.Group();camera.add(gun);scene.add(camera);const gunMat=new THREE.MeshStandardMaterial({color:0x202c32,metalness:.8,roughness:.34}),gunEdge=new THREE.MeshStandardMaterial({color:0x698087,metalness:.9,roughness:.26}),gunGlow=new THREE.MeshStandardMaterial({color:0x65eef0,emissive:0x2ccbd0,emissiveIntensity:2});
function weaponModel(type){while(gun.children.length)gun.remove(gun.children[0]);const base=new THREE.Mesh(new THREE.BoxGeometry(.24,.19,.56),gunMat);base.position.set(.32,-.28,-.55);gun.add(base);const grip=new THREE.Mesh(new THREE.BoxGeometry(.12,.22,.16),gunMat);grip.position.set(.32,-.42,-.42);grip.rotation.x=-.2;gun.add(grip);const barrel=new THREE.Mesh(new THREE.CylinderGeometry(.045,.065,.5,8),gunEdge);barrel.rotation.x=Math.PI/2;barrel.position.set(.32,-.23,-.88);gun.add(barrel);const rail=new THREE.Mesh(new THREE.BoxGeometry(.07,.045,.36),gunGlow);rail.position.set(.32,-.15,-.56);gun.add(rail);
if(type===1){base.scale.set(1.05,.82,1.05);const side=new THREE.Mesh(new THREE.BoxGeometry(.09,.13,.32),gunGlow);side.position.set(.44,-.24,-.58);gun.add(side);for(let i=0;i<3;i++){const coil=new THREE.Mesh(new THREE.TorusGeometry(.065,.018,5,12),gunEdge);coil.rotation.x=Math.PI/2;coil.position.set(.32,-.23,-.62-i*.1);gun.add(coil)}}
if(type===2){base.scale.set(1.35,1.25,1.5);barrel.scale.set(1.8,1.25,1.5);const drum=new THREE.Mesh(new THREE.CylinderGeometry(.12,.12,.19,10),gunEdge);drum.rotation.z=Math.PI/2;drum.position.set(.4,-.32,-.52);gun.add(drum);const warning=new THREE.Mesh(new THREE.BoxGeometry(.18,.055,.17),mats.amber);warning.position.set(.32,-.15,-.42);gun.add(warning)}gun.rotation.y=-.035;}
const weapons=[{name:'VANTA // CARBINE',mag:24,ammo:24,reserve:144,damage:34,rate:.19,reload:1.35,spread:.012,type:0},{name:'ROOK // PULSE',mag:48,ammo:48,reserve:240,damage:15,rate:.075,reload:1.7,spread:.027,type:1},{name:'BASTION // LAUNCHER',mag:5,ammo:5,reserve:30,damage:100,rate:.72,reload:2.1,spread:.01,type:2}];let weaponIndex=0;weaponModel(0);
const raycaster=new THREE.Raycaster();raycaster.far=75;const clock=new THREE.Clock();
function showToast(t){const el=document.getElementById('toast');el.textContent=t;toastTimer=1.5}
function refreshHud(){const w=weapons[weaponIndex];document.getElementById('healthText').textContent=Math.ceil(playerHealth);document.getElementById('healthBar').style.width=Math.max(0,playerHealth)+'%';document.getElementById('armorText').textContent=Math.ceil(armor);document.getElementById('armorBar').style.width=Math.max(0,armor*2)+'%';document.getElementById('weaponName').textContent=w.name;document.getElementById('ammoText').textContent=w.ammo;document.getElementById('reserveText').textContent=w.reserve;document.getElementById('waveText').textContent=gameMode==='survival'?`WAVE ${String(wave).padStart(2,'0')}`:'TARGET RANGE';document.getElementById('waveSub').textContent=gameMode==='survival'?`${enemies.length} HOSTILES ACTIVE`:`${accuracyHits} / ${accuracyShots} HITS`;document.getElementById('scoreText').textContent=String(score).padStart(6,'0')}
function updateMap(){const c=document.getElementById('map'),ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#101a21';ctx.fillRect(0,0,c.width,c.height);ctx.strokeStyle='#40545b';ctx.lineWidth=7;ctx.strokeRect(12,12,252,252);ctx.strokeStyle='#304148';ctx.lineWidth=4;for(const [x,z,w,d] of [[-5,-4,2.8,1.25],[5,-4,2.8,1.25],[-5,4,2.8,1.25],[5,4,2.8,1.25],[0,-10.5,14,2.3],[0,10.5,14,2.3]])ctx.strokeRect(138+x*5-w*2.5,138+z*5-d*2.5,w*5,d*5);ctx.fillStyle='#53e6ee';ctx.beginPath();ctx.arc(138+player.pos.x*5,138+player.pos.z*5,6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#53e6ee';ctx.beginPath();ctx.moveTo(138+player.pos.x*5,138+player.pos.z*5);ctx.lineTo(138+player.pos.x*5-Math.sin(player.yaw)*12,138+player.pos.z*5-Math.cos(player.yaw)*12);ctx.stroke();for(const e of enemies){ctx.fillStyle=e.type===2?'#ff5266':'#ffb34e';ctx.beginPath();ctx.arc(138+e.group.position.x*5,138+e.group.position.z*5,5,0,Math.PI*2);ctx.fill()}}
function setWeapon(i){weaponIndex=(i+3)%3;weaponModel(weaponIndex);refreshHud();showToast(weapons[weaponIndex].name)}
