function makeEnemy(type=0,at=null,target=false,moving=false){const group=new THREE.Group(),mat=new THREE.MeshStandardMaterial({color:type===2?0x4c4442:type===1?0x3c4652:0x344950,metalness:.72,roughness:.43}),glow=new THREE.MeshStandardMaterial({color:type===2?0xff7448:0xffa74a,emissive:type===2?0xf1391d:0xf87412,emissiveIntensity:2});const scale=type===2?1.32:type===1?.83:1;group.scale.setScalar(scale);const torso=new THREE.Mesh(new THREE.BoxGeometry(.78,.92,.44),mat);torso.position.y=1.15;torso.castShadow=true;group.add(torso);const head=new THREE.Mesh(new THREE.BoxGeometry(.48,.4,.4),mat);head.position.set(0,1.88,0);head.castShadow=true;group.add(head);const eye=new THREE.Mesh(new THREE.BoxGeometry(.3,.075,.05),glow);eye.position.set(0,1.91,-.22);group.add(eye);for(const s of [-1,1]){const limb=new THREE.Mesh(new THREE.BoxGeometry(.21,type===2?.75:.65,.24),mat);limb.position.set(s*.53,1.2,0);limb.castShadow=true;group.add(limb);const leg=new THREE.Mesh(new THREE.BoxGeometry(.27,.58,.3),mat);leg.position.set(s*.22,.39,0);leg.castShadow=true;group.add(leg)}const pack=new THREE.Mesh(new THREE.BoxGeometry(.62,.54,.25),mats.dark);pack.position.set(0,1.3,.32);group.add(pack);for(let s of [-1,1]){const vent=new THREE.Mesh(new THREE.BoxGeometry(.08,.27,.03),glow);vent.position.set(s*.18,1.3,.47);group.add(vent)}
const barBg=new THREE.Mesh(new THREE.PlaneGeometry(1.05,.1),new THREE.MeshBasicMaterial({color:0x351b20,side:THREE.DoubleSide}));barBg.position.y=2.48;group.add(barBg);const barFill=new THREE.Mesh(new THREE.PlaneGeometry(1,.065),new THREE.MeshBasicMaterial({color:0x59e5de,side:THREE.DoubleSide}));barFill.position.set(0,2.48,-.006);group.add(barFill);
const spawn=at||(()=>{let a=Math.random()*Math.PI*2,r=14+Math.random()*4;return new THREE.Vector3(Math.cos(a)*r,0,Math.sin(a)*r)})();group.position.set(spawn.x,0,spawn.z);scene.add(group);const data={group,type,hp:type===2?300:type===1?105:75,max:type===2?300:type===1?105:75,target,moving,speed:type===2?1.55:type===1?3.5:2.4,attack:1.2+Math.random(),barFill,parts:[torso,head,eye],phase:Math.random()*6,alive:true};enemies.push(data);return data}
function spawnWave(){let count=Math.min(3+wave*2,16);for(let i=0;i<count;i++){const type=wave>=3&&i%5===0?2:wave>=2&&i%3===0?1:Math.random()<.24?1:0;setTimeout(()=>{if(running&&gameMode==='survival')makeEnemy(type)},i*420)}}
function spawnPractice(){for(let i=0;i<6;i++)makeEnemy(i%3===0?1:0,new THREE.Vector3([-12,-7,0,8,14,4][i],0,[-10,-13,-18,-12,-8,2][i]),true,i===1||i===4)}
function removeEnemy(e){scene.remove(e.group);const i=enemies.indexOf(e);if(i>=0)enemies.splice(i,1);e.alive=false}
function burst(pos,color=0x44e7ef,big=false){const g=new THREE.Group();g.position.copy(pos);scene.add(g);const n=big?18:8;for(let i=0;i<n;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(big?.11:.055,6,5),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.95}));m.position.set(0,0,0);g.add(m);const v=new THREE.Vector3(Math.random()-.5,Math.random()-.15,Math.random()-.5).normalize().multiplyScalar((big?3:2)+Math.random()*2);effects.push({mesh:m,vel:v,life:.35+Math.random()*.38,max:.73})}if(big){const ring=new THREE.Mesh(new THREE.TorusGeometry(.3,.07,6,16),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.8}));ring.position.copy(pos);ring.rotation.x=Math.PI/2;scene.add(ring);effects.push({mesh:ring,vel:new THREE.Vector3(0,1.4,0),life:.42,max:.42,ring:true})}}
