function enemyFire(e){const start=e.group.position.clone().add(new THREE.Vector3(0,1.35,0));const dir=player.pos.clone().sub(start).normalize();const m=new THREE.Mesh(new THREE.SphereGeometry(e.type===2?.18:.12,8,8),new THREE.MeshBasicMaterial({color:e.type===2?0xff5645:0xffb747}));m.position.copy(start);scene.add(m);shots.push({mesh:m,vel:dir.clone().multiplyScalar(e.type===2?9:13),life:4,damage:e.type===2?16:9})}
function enemyStep(e,dt){if(e.target&&gameMode==='practice'){e.group.position.z+=Math.sin(elapsed*.9+e.phase)*dt*(e.moving?1.15:0);e.group.position.x+=Math.cos(elapsed*.65+e.phase)*dt*(e.moving?.7:0);e.group.rotation.y=Math.atan2(player.pos.x-e.group.position.x,player.pos.z-e.group.position.z);return}const p=e.group.position,dx=player.pos.x-p.x,dz=player.pos.z-p.z,dist=Math.hypot(dx,dz),ang=Math.atan2(dx,dz);e.group.rotation.y=ang;e.attack-=dt;if(dist>6.8){const nx=dx/(dist||1),nz=dz/(dist||1);let tx=p.x+nx*e.speed*dt,tz=p.z+nz*e.speed*dt;if(!blocked(tx,tz,.65)){p.x=tx;p.z=tz}else{const side=((Math.floor(e.phase*10)%2)?1:-1);tx=p.x+nz*e.speed*dt*side;tz=p.z-nx*e.speed*dt*side;if(!blocked(tx,tz,.65)){p.x=tx;p.z=tz}}}else if(dist<4){p.x-=dx/(dist||1)*e.speed*.5*dt;p.z-=dz/(dist||1)*e.speed*.5*dt}if(e.attack<=0&&dist<25){enemyFire(e);e.attack=(e.type===2?1.8:1.25)+Math.random()*.75}e.phase+=dt*6;for(const child of e.group.children)if(child.geometry?.type==='BoxGeometry'&&child.position.y<.8)child.rotation.x=Math.sin(e.phase)*.18;e.group.children[0].material.color.setHex(e.group.userData.flash?0x9fffff:undefined);if(e.group.userData.flash)e.group.userData.flash-=dt;e.barFill.quaternion.copy(camera.quaternion);e.group.children.find(c=>c===e.barFill)?.quaternion.copy(camera.quaternion)}
function blocked(x,z,r){for(const s of solids){const b=s.box;if(b.max.y<.4||b.min.y>2.2)continue;if(x+r>b.min.x&&x-r<b.max.x&&z+r>b.min.z&&z-r<b.max.z)return true}return false}

